constraints:
1 ≤ N ≤ 10^{7}
0 ≤ arr_{i} ≤ 10^{7}

expected time complexity: O(N)
expected auxiliary space: O(1)

standard_solution_code:
class Solution:

	def minJumps(self, arr, n):
		curend = 0
		curfar = 0
		ans = 0
		for i in range(n):
			curfar = max(curfar, i + arr[i])
			if curfar >= n - 1:
				ans += 1
				break
			if i == curend:
				ans += 1
				curend = curfar
			if curfar <= i:
				break
		if curfar < n - 1:
			return -1
		return ans
